describe('Character Count on Textarea', () => {
  beforeEach(() => {
    cy.visit('/form');
  });

  it('should display character count and limit input to 500 characters', () => {
    // Verify textarea and character count element are visible
    cy.get('[data-testid="textarea-input"]').should('be.visible');
    cy.get('[data-testid="char-count"]').should('be.visible');
    cy.get('[data-testid="char-count"]').should('contain', '0/500');

    // Type less than 500 characters
    cy.get('[data-testid="textarea-input"]').type('This is a test message');
    cy.get('[data-testid="char-count"]').should('contain', '21/500');

    // Type exactly 500 characters
    const longText = 'a'.repeat(479);
    cy.get('[data-testid="textarea-input"]').type(longText);
    cy.get('[data-testid="char-count"]').should('contain', '500/500');

    // Attempt to type one more character (should be blocked)
    cy.get('[data-testid="textarea-input"]').type('a');
    cy.get('[data-testid="textarea-input"]').should('have.value', 'a'.repeat(500));
    cy.get('[data-testid="char-count"]').should('contain', '500/500');

    // Verify submit button is enabled
    cy.get('[data-testid="submit-button"]').should('not.be.disabled');
  });

  it('should handle empty textarea and display correct count', () => {
    // Verify textarea is empty
    cy.get('[data-testid="textarea-input"]').should('have.value', '');
    cy.get('[data-testid="char-count"]').should('contain', '0/500');

    // Clear existing text
    cy.get('[data-testid="textarea-input"]').clear();
    cy.get('[data-testid="char-count"]').should('contain', '0/500');

    // Type a short message
    cy.get('[data-testid="textarea-input"]').type('Hello');
    cy.get('[data-testid="char-count"]').should('contain', '5/500');

    // Verify submit button is disabled when textarea is empty
    cy.get('[data-testid="submit-button"]').should('be.disabled');

    // Type a message that is exactly 1 character
    cy.get('[data-testid="textarea-input"]').clear();
    cy.get('[data-testid="textarea-input"]').type('a');
    cy.get('[data-testid="char-count"]').should('contain', '1/500');
    cy.get('[data-testid="submit-button"]').should('not.be.disabled');
  });
});
